fn numpy_greater_equal(x1: Vec<i8>, x2: Vec<i8>) -> Vec<bool> {
    // Ensure both input arrays have the same length
    assert_eq!(x1.len(), x2.len(), "Input arrays must have equal length");

    // For each position, check if x1[i] >= x2[i]
    x1.iter()
      .zip(x2.iter())
      .map(|(&a, &b)| a >= b)
      .collect()
}

